// ProjectView is a Project as every read returns it.
export interface ProjectView {
  key: string;
  display_name: string;
  created: string;
  mode: Mode;
  archived: boolean;
  // ArchivedAt is when the human archived the Project, while it is.
  archived_at?: string;
  // Landing is how the Project's accepted work lands, always filled in:
  // merge, push off, origin by default.
  landing: LandingView;
  // CI is the Project's CI settings, always filled in: CI Tracking off
  // by default.
  ci: CIView;
  // GitHubIssues is the Project's GitHub Issues settings, always filled
  // in: GitHub Issues off by default.
  github_issues: GitHubIssuesView;
  // AzureBoards is the Project's Azure Boards settings, always filled
  // in: Azure Boards off by default.
  azure_boards: AzureBoardsView;
  // Models is the Project's Models rows, always filled in: every row at
  // Default to begin with.
  models: ModelsView;
  // ReportedModels is what the Factory last reported its claude
  // accepts, always filled in: no aliases or model IDs, and the seeded
  // effort levels, until a Factory reports.
  reported_models: ReportedModelsView;
  // StageGuides is the Project's Stage Guides settings, always filled
  // in: Subagent Exploration on by default.
  stage_guides: StageGuidesView;
  // AutoAccept is the Project's Auto-accept setting, one entry per
  // Auto-accept kind, always filled in: every kind off by default.
  auto_accept: Partial<Record<AutoAcceptKind, boolean>>;
  // FocusKinds is the Project's Focus Kinds, always filled in: every
  // Needs Me reason on by default.
  focus_kinds: FocusKindsView;
  // FactoryStatus is whether the Project's Factories are online, from
  // their Heartbeats, always filled in: offline, with no Factories,
  // until one sends a Heartbeat.
  factory_status: FactoryStatusView;
  // Repositories are the Project's Repositories in landing order, always
  // filled in: the Home Repository alone until the human adds another.
  repositories: RepositoryView[];
}

// ProjectRow is one list_projects row: the Project and how many of its
// Tickets need the human.
export interface ProjectRow extends ProjectView {
  needs_me: number;
  // Unfinished counts the Tickets not yet Done or Cancelled; archiving
  // waits for it to reach zero.
  unfinished: number;
}

// TargetView is a Spec's or Ticket's Labels and Tags, as the Label and
// Tag operations return them.
export interface TargetView {
  id: string;
  kind: RecordKind;
  labels: string[];
  tags: Record<string, string>;
}

// LinkedRow is a linked Spec or Ticket as the link operations return it.
// State is set for a Ticket.
export interface LinkedRow {
  kind: RecordKind;
  id: string;
  title: string;
  state?: State;
  link: LinkView;
}

// TicketView is the full view of one Ticket, as its writes return it with
// full. A read (get_ticket, claim) may leave parts out: each part left out
// is nil, so it has no key, and LeftOut counts what it had.
export interface TicketView {
  id: string;
  title: string;
  state: State;
  spec: SpecRef;
  labels: string[];
  tags: Record<string, string>;
  blocked_by: string[];
  blockers: BlockerView[];
  replacements: string[];
  created: string;
  updated: string;
  description: string;
  // Branch and Commit are the work's branch and head commit in the Home
  // Repository, as the last finish naming them gave them. Work with a
  // branch is Accepted, then lands.
  branch?: string;
  commit?: string;
  // Repositories are the Ticket's Changed Repositories, in landing
  // order: live while it is In Progress, as the Factory reports them,
  // and settled by each finish. Left out while the Project has the Home
  // Repository alone, whose work Branch and Commit give.
  repositories?: ChangedRepositoryView[];
  // PartlyLanded says the Ticket is Accepted and has landed in some of
  // its Changed Repositories but not all. Computed on read.
  partly_landed?: boolean;
  // Recommendation is a spec Stage's Spec recommendation, as its last
  // finish gave it: implement (Implement) or split (Split into
  // Tickets); empty on any other Ticket.
  recommendation?: Recommendation;
  // PushedCommit is the latest commit the Factory pushed for the Ticket
  // in the Home Repository while CI Tracking was on, and CICommit the
  // pushed commit there the Home Repository's CI result comes from:
  // under the CI gate one that passed, if any did, else the latest
  // (code-central-430). CIResult is the Ticket's CI result, combined
  // across its watched Repositories: running, else failed, else
  // cancelled, else passed; each Repository's own is in Repositories.
  // All are left out while it has none. CIRuns are every CI Run tracked
  // against it, the Home Repository's first, each Repository's latest
  // pushed commit's first. Computed on read.
  pushed_commit?: PushedCommitView;
  // PullRequest is the pull request the Pull Request Watcher reported
  // for the Ticket's pushed work; left out until it has one.
  pull_request?: PullRequestView;
  ci_result?: CIResult;
  ci_commit?: string;
  ci_runs?: CIRunView[];
  // LandAnyway says the human accepted the failed CI result of the
  // latest pushed commit in the Home Repository, so the Factory lands it
  // there (code-central-261), on this Ticket or on another sharing the
  // commit (code-central-432).
  land_anyway?: boolean;
  // CIAutoFix is what Auto-fix does about the Ticket's CI failure in the
  // Home Repository: the auto fix Ticket fixing it, the one covering it,
  // or the chain it stopped at the limit; left out while it does
  // nothing. Each Repository's own is in Repositories. Computed on read.
  ci_auto_fix?: CIAutoFixView;
  // SpecLanded says Land per Spec covers the Ticket, and WaitingForSpec
  // that it is Accepted and waits for its Spec to land (code-central-371).
  // Computed on read.
  spec_merge?: SpecMergeView;
  spec_landed?: boolean;
  // CIItem is the CI failed, CI cancelled or CI unavailable item that
  // lists this Ticket, with every other Ticket waiting on its pushed
  // commit (code-central-432); left out while none does. A Ticket listed
  // in several Repositories has the first in landing order whose reason
  // is its own here, and CIItems lists each one, but only while the
  // Project has more than one Repository.
  ci_item?: CIItemView;
  ci_items?: CIItemView[];
  waiting_for_spec?: boolean;
  // CIFailureOptions are the failure options, each an operation's name,
  // the human may choose on the Ticket's CI item while it is CI failed
  // or CI cancelled, acting on every Ticket it lists; left out
  // otherwise, and empty when none applies. Computed on read.
  ci_failure_options?: CIFailureOption[];
  claims?: ClaimView[];
  rounds?: RoundView[];
  failure_reports?: FailureReportView[];
  comments?: CommentView[];
  moves?: MoveView[];
  edits?: EditView[];
  // LeftOut counts each part a read left out that has anything, by
  // part name.
  left_out?: Record<string, number>;
  blocked: boolean;
  claimable: boolean;
  // Editable says the UI offers Edit on the Ticket, and Retroable its
  // Retro button, as ticketEditable and ticketRetroable decide them.
  // Every read sets them. Computed on read.
  editable: boolean;
  retroable: boolean;
  // SilentSince is set while the Ticket is a Silent Claim: In Progress
  // with no activity for 30 minutes. It is the time of the last
  // activity, so the quiet time is now minus it. Computed, never stored.
  silent_since?: string;
  // NeedsMeReason says why the Ticket waits on the human, if it does.
  needs_me_reason?: NeedsMeReason;
  // Link is set on a linked Ticket (ticket 42).
  link?: LinkView;
  // AwaitingTriage is set on an Incoming Issue that came in while New
  // issues need me was on and that the human hasn't triaged yet.
  awaiting_triage?: boolean;
  // SpecMergeTicket marks a Spec merge Ticket, one open_spec_merge
  // opened; left out on any other Ticket.
  spec_merge_ticket?: boolean;
  // AutoFix is an auto fix Ticket's Auto-fix mark; left out on any
  // other Ticket, a manual fix Ticket too.
  auto_fix?: AutoFixMarkView;
  // TriageActions are the triage actions, each an operation's name, the
  // human may take on an Incoming Issue; left out on any other Ticket.
  // Computed on read.
  triage_actions?: TriageAction[];
  // TriageNotes say what each of TriageActions does to the linked issue
  // or work item, as the UI shows it before the human confirms; left out
  // on any other Ticket. Computed on read.
  triage_notes?: Partial<Record<TriageAction, string>>;
  // ModelChoice is the model and effort the Ticket's next turn runs
  // with, each with its source; only the UI's read carries it.
  model_choice?: ModelChoice;
  // Retros are the Retros looking back on this Ticket, oldest first;
  // left out when there are none. Only get_ticket sets it.
  retros?: RetroView[];
  // AutoAcceptKind is the Ticket's Auto-accept kind (grilling, spec,
  // tickets, implementation or merge); left out when it has none. Only
  // the UI's read carries it.
  auto_accept_kind?: AutoAcceptKind;
}

// TicketRow is one find_tickets result.
export interface TicketRow {
  id: string;
  title: string;
  state: State;
  spec: string;
  labels: string[];
  blocked: boolean;
  created: string;
  updated: string;
  link?: LinkView;
  // NodeType is the Ticket's type on a Map (see NodeTypeOf); left out
  // for a Ticket on any other Spec.
  node_type?: NodeType;
  // BlockedBy is the Ticket's Blockers on a Map, the Map view's edges;
  // left out for a Ticket on any other Spec.
  blocked_by?: string[];
  // LatestEvent is the latest Session Event of the Ticket's live Claim,
  // shown short; left out when there is none.
  latest_event?: LatestEvent;
  // CIResult is the Ticket's CI result, for its row's badge; left out
  // for a Ticket never pushed while CI Tracking was on.
  ci_result?: CIResult;
  // PullRequest is the Ticket's pull request, for its row's badge; left
  // out until the Pull Request Watcher reports one.
  pull_request?: PullRequestView;
  // WaitingForSpec says the Ticket is Accepted and waits for its Spec to
  // land, for its badge (code-central-371).
  waiting_for_spec?: boolean;
  // NeedsMeReason says why the Ticket waits on the human, if it does:
  // the reason get_ticket gives, a CI item's for a Ticket it lists.
  needs_me_reason?: NeedsMeReason;
  // Repositories are the Names of the Ticket's Changed Repositories, in
  // landing order, for its card's chips; left out while the Project has
  // the Home Repository alone.
  repositories?: string[];
  // PartlyLanded says the Ticket is Accepted and has landed in some of
  // its Changed Repositories but not all, for its card's badge.
  partly_landed?: boolean;
}

// SpecDetail is get_spec's result: the Spec, its State summary and its
// Tickets as find_tickets rows (finished ones too), in claim order. Its
// first fields are SpecView's, in its order, so the full read is the
// SpecView it used to embed; a lighter read leaves out each part not asked
// for (nil, so it has no key) and adds the body's Outline.
export interface SpecDetail {
  id: string;
  title: string;
  labels: string[];
  tags: Record<string, string>;
  created: string;
  updated: string;
  body?: string;
  edits?: EditView[];
  // Link is set on a linked Spec (ticket 42).
  link?: LinkView;
  // Outline is every heading of the whole body, on a lighter read only.
  outline?: Heading[];
  state_summary: Partial<Record<State, number>>;
  finished: boolean;
  // Kind, Need and Claimed are as on SpecRow.
  kind: SpecKind;
  need?: NeedsMeReason;
  claimed: boolean;
  // Editable says the UI offers Edit on the Spec, and Retroable its
  // Retro button, as specEditable and specRetroable decide them. Every
  // read sets them.
  editable: boolean;
  retroable: boolean;
  // Repositories are the Spec's Changed Repositories, the union of its
  // Tickets', by Name in landing order; left out while the Project has
  // the Home Repository alone.
  repositories?: string[];
  tickets?: TicketRow[];
  // Requirement is set only when the Spec is a Requirement.
  requirement?: RequirementView;
  // LandPerSpec is the Spec's Land per Spec status, left out unless it is
  // a Long-lived Spec or the Project isn't under Merge or Pull Request
  // with Land per Spec on.
  land_per_spec?: LandPerSpecView;
  // Retros are the Retros looking back on this Spec, oldest first; left
  // out when there are none.
  retros?: RetroView[];
  // Map is set only when the Spec is a Map.
  map?: MapView;
}

// SpecRow is one find_specs result.
export interface SpecRow {
  id: string;
  title: string;
  labels: string[];
  tags: Record<string, string>;
  state_summary: Partial<Record<State, number>>;
  finished: boolean;
  updated: string;
  link?: LinkView;
  // Kind is the Spec's kind, for its badge.
  kind: SpecKind;
  // Need is the reason of the first of its Tickets, in claim order,
  // that waits on the human, as Needs Me reads it; left out when none
  // does. Claimed says any of its Tickets holds a live Claim. A plain
  // Spec's headline says them. Computed at read time.
  need?: NeedsMeReason;
  claimed: boolean;
  // Requirement is set only when the Spec is a Requirement.
  requirement?: RequirementView;
  // Map is set only when the Spec is a Map.
  map?: MapView;
}

// SpecQuestions is get_spec_questions' result: the roll-up of a Spec's
// Questions. Questions sit only on Tickets, so it lists each of the Spec's
// Tickets that has Rounds, in claim order, with its Rounds.
export interface SpecQuestions {
  spec: string;
  tickets: TicketQuestions[];
}

// NeedsMeView is needs_me: everything waiting on the human across every
// Project, in groups in group order (empty groups left out), each group
// longest-waiting first. Every view renders this order as it comes.
export interface NeedsMeView {
  // Count is the Needs Me count across every Project: the sum of
  // Counts.
  count: number;
  // Counts is the Needs Me count of each Project, left out while it has
  // nothing in Needs Me.
  counts: Record<string, number>;
  groups: NeedsMeGroup[];
}

// TranscriptView is a Claim's Transcript as the read returns it: the held
// events, oldest first. Tail is true when it holds only part of the
// session: events were dropped from its front, as it keeps the last
// TranscriptLimit, or it began after the Claim did, as none are kept
// from before Code Central's last restart.
export interface TranscriptView {
  events: HeldSessionEvent[];
  tail: boolean;
}

// CIOverview is the CI view: the CI Watchers' statuses, then the runs,
// in-progress ones first, newest started first, then those finished in
// the last ciViewDays days, newest finished first. A run re-run lists its
// latest attempt only.
export interface CIOverview {
  projects: CIProjectStatus[];
  runs: CIRunRow[];
}

// UsageView is Usage as the read returns it. Kinds, Sessions and Days
// come from the token usage a Factory posts: Kinds over every session,
// main and Subagent; Sessions the main sessions, newest first and at
// most RecentSessions, each with all its Subagents; and Days a row for
// every local day in the range, oldest first.
export interface UsageView {
  operations: UsageOperation[];
  kinds: UsageKind[];
  sessions: UsageSession[];
  days: UsageDay[];
}

// SessionUsageView is one session's responses, oldest first, for its
// line chart. For a Subagent it also has its Agent Type and description,
// the latest non-empty of each among its responses.
export interface SessionUsageView {
  agent_type?: string;
  description?: string;
  responses: SessionUsageResponse[];
}

// ConversationView is a Project's current Conversation as get_chat and
// the Chat writes return it. With none, Availability is none and the rest
// is empty.
export interface ConversationView {
  availability: ChatAvailability;
  id?: string;
  model?: string;
  // Effort is empty for Claude Code's default.
  effort?: string;
  // Factory is the Factory holding the Conversation, left out until one
  // takes its first turn.
  factory?: ChatFactory;
  // Running says a reply is pending or running.
  running: boolean;
  // Tail says older Chat Messages were dropped from the front.
  tail: boolean;
  // SessionID and ResumeCommand are as the Factory reported them, empty
  // until it does.
  session_id?: string;
  resume_command?: string;
  messages: ChatMessageView[];
}

// OptionsView is the Options as every front door shows them.
export interface OptionsView {
  focus_clear: FocusClear;
  // FocusPopup is the Focus Pop-up Option.
  focus_popup: FocusPopup;
  // LimitsPopup is the Show Limits popup Option.
  limits_popup: LimitsPopup;
  // GHPath is the gh path Option: where gh is, "" to find it on the
  // service's PATH, then in the usual install places.
  gh_path: string;
}

// Acknowledgement is a write's short result: what it wrote, never the
// values it wrote.
export interface Acknowledgement {
  id: string;
  updated: string;
  // Changed names the record's fields the write changed, in the record
  // view's field order, never updated. Empty when nothing changed.
  changed: string[];
  // Edit is the number of the edit the write recorded, if it recorded one.
  edit?: number;
  // State is a Ticket's State after the write; a Spec has none.
  state?: State;
}

// SpecView is a Spec as every read returns it, and as its writes return
// it with full.
export interface SpecView {
  id: string;
  title: string;
  labels: string[];
  tags: Record<string, string>;
  created: string;
  updated: string;
  body: string;
  edits: EditView[];
  // Link is set on a linked Spec (ticket 42).
  link?: LinkView;
}

// LandingView is a Project's Landing Method with its Push option and the
// remote it uses.
export interface LandingView {
  method: LandingMethod;
  push: boolean;
  remote: string;
  // LandPerSpec is the Merge option to land a Spec's work together,
  // shown whatever the method.
  land_per_spec: boolean;
  // CodeHost is the Code Host the reported Push remote URL names,
  // github or azure_repos, empty while none is reported or it is
  // unsupported. Repository is the host's name for the repository.
  code_host: CodeHost;
  repository: string;
  // PATEnv is the environment variable holding the Azure Repos PAT,
  // ADO_PAT unless the Project names another.
  pat_env: string;
  // UsesAzureReposPAT is whether the PAT variable is used: any Azure
  // Repos Repository is under Pull Request.
  uses_azure_repos_pat: boolean;
  // Base is the branch the Project's work is cut from and lands on: the
  // stored one, else the reported fallback, else main.
  base: string;
  // Methods is the Landing capabilities of each Landing Method, as if
  // it were the Default Landing: what the Options form offers while the
  // human drafts it.
  methods: LandingMethodsCapabilities;
  // RunsPullRequestWatcher is whether the Pull Request Watcher runs, as
  // saved: any Repository is under Pull Request.
  runs_pull_request_watcher: boolean;
  // RepositoryLanding is the Default Landing named as a Repository's
  // Landing names it.
  repository_landing: RepositoryLanding;
  // PushesNothing is whether Push is on in some Landing while every
  // Repository is local-only, so it pushes nothing.
  pushes_nothing: boolean;
  // Watcher is the Pull Request Watcher's status, not_reported unless the
  // method is Pull Request.
  watcher: WatcherView;
  // OpenPullRequests are the pull requests left open on the Code Host
  // after a switch away from Pull Request, one per Ticket's, until the
  // Ticket leaves Accepted. Always empty under Pull Request.
  open_pull_requests: OpenPullRequest[];
}

// CIView is a Project's CI settings as every Project read returns them.
export interface CIView {
  tracking: boolean;
  // Provider, Repository and ProjectURL are the Home Repository's CI
  // entry as stored, for an older client, which set it here: GitHub
  // Actions naming nothing while none is. Its Repository view's CI is
  // its CI choice, filled in from its Clone URL while none is stored.
  provider: CIProvider;
  // Repository is the GitHub repository GitHub Actions watches.
  repository: string;
  // ProjectURL is the Azure DevOps project Azure Pipelines watches.
  project_url: string;
  // PATEnv is the name of the environment variable holding the Azure
  // DevOps PAT, ADO_PAT unless the Project names another. The PAT itself
  // is never kept.
  pat_env: string;
  // IgnoredWorkflows are workflow names, such as the workflow file
  // ci.yml or a pipeline's name, whose runs never count towards a CI
  // result.
  ignored_workflows: string[];
  // PushRemoteURL is the URL of the Push remote the Factory last
  // reported, empty until it has.
  push_remote_url: string;
  // Rules are the CI Rules, in the order they were added.
  rules: CIRuleView[];
  // Watcher is the CI Watcher's status, as it last reported it.
  watcher: WatcherView;
  // Repositories are the CI entries of the Repositories other than the
  // Home, in landing order; Provider, Repository and ProjectURL are the
  // Home Repository's, and the PAT environment variable, Ignored
  // workflows and CI Rules are every Repository's. Left out while the
  // Project has the Home Repository alone.
  repositories?: CIRepositoryView[];
  // AutoFix is the Auto-fix setting, kept while CI Tracking is off.
  auto_fix: AutoFixView;
}

// GitHubIssuesView is a Project's GitHub Issues settings as every Project
// read returns them.
export interface GitHubIssuesView {
  on: boolean;
  // Repositories are the GitHub repositories (owner/name) its issues
  // come from, in the order the human listed them.
  repositories: string[];
  // Label is the filter label: only issues carrying it come in; empty
  // lets every issue in.
  label: string;
  new_issues_need_me: boolean;
  // Spec is the Issues Spec's ID, left out until GitHub Issues is first
  // turned on.
  spec?: string;
  // Watcher is the Issue Watcher's status, as it last reported it.
  watcher: WatcherView;
}

// AzureBoardsView is a Project's Azure Boards settings as every Project
// read returns them.
export interface AzureBoardsView {
  on: boolean;
  // Mode is how it picks its work items: saved_query or wiql.
  mode: AzureBoardsMode;
  // QueryURL is the Saved query's URL.
  query_url: string;
  // ProjectURL is the Azure DevOps project a WIQL filter runs in, and
  // Where its WHERE clause.
  project_url: string;
  where: string;
  // PATEnv is the name of the environment variable holding the Azure
  // DevOps PAT: the Project's CI PAT variable, ADO_PAT unless it names
  // another, unless Azure Boards names its own. The PAT itself is never
  // kept.
  pat_env: string;
  new_issues_need_me: boolean;
  // Spec is the Azure Boards Spec's ID, left out until Azure Boards is
  // first turned on.
  spec?: string;
  // Watcher is the Work Item Watcher's status, as it last reported it.
  watcher: WatcherView;
}

// ModelsView is a Project's Models as every Project read returns them:
// the Project default row, the Chat row, then one row for every kind of
// work, in GuideNames order, each empty where it sets nothing. The Chat
// row is not a kind of work (Spec code-central-633): Chat doesn't use the
// default row, so a costly default doesn't make Chat costly.
export interface ModelsView {
  default: ModelRowView;
  chat: ModelRowView;
  kinds: KindModelsView[];
}

// ReportedModelsView is a Project's Reported Models as every Project read
// returns them: what its Factory last reported, plus the model IDs its
// sessions' usage has shown.
export interface ReportedModelsView {
  // EffortLevels are the valid effort levels: the reported ones, or the
  // seeded ones until a report has given some.
  effort_levels: string[];
  aliases: string[];
  model_ids: string[];
  // ModelFlag and EffortFlag are the Factory's --model and --effort,
  // empty when it reported them unset or hasn't reported.
  model_flag: string;
  effort_flag: string;
  // Reported is when the Factory last reported, left out before any
  // report.
  reported?: string;
}

// StageGuidesView is a Project's Stage Guides settings as every Project
// read returns them.
export interface StageGuidesView {
  // SubagentExploration is whether the implementation guide tells the
  // agent to send reading across several files to a subagent.
  subagent_exploration: boolean;
  // ModelAssignment is whether the tickets Stage sets each Ticket's
  // model and effort.
  model_assignment: boolean;
}

// FocusKindsView is a Project's Focus Kinds as every Project read returns
// them: the Needs Me reasons that are off, in group order, empty while
// every reason is on.
export interface FocusKindsView {
  off: NeedsMeReason[];
}

// FactoryStatusView is a Project's Factory Status as every Project read
// returns it, always filled in.
export interface FactoryStatusView {
  // Status is the combined status: Online if any Factory is, else
  // Draining if any is, else Offline (also with no Factories).
  status: FactoryStatusName;
  factories: FactoryView[];
  // Base is the base the Factory last reported under Pull Request
  // (code-central-394); left out while none is reporting.
  base?: BaseView;
  // PlanLimits are the most recently observed Plan Limits among the
  // Factories that aren't Offline (Spec code-central-861); left out
  // while none has any.
  plan_limits?: PlanLimits;
}

// RepositoryView is one of a Project's Repositories as every Project read
// returns it, in landing order.
export interface RepositoryView {
  name: string;
  // Home marks the Home Repository, named by the Project Key.
  home: boolean;
  // CloneURL is the remote the Repository is cloned from and pushed to:
  // the Push remote URL the Factory reported for the Home Repository,
  // empty until it has, or when it reported none.
  clone_url: string;
  // LocalOnly marks a Repository with no Clone URL, never cloned or
  // pushed: the Home Repository once the Factory reports its clone has
  // no Push remote, and not before.
  local_only: boolean;
  // Base is the branch its work is cut from and lands on: the Project's
  // Base for the Home Repository.
  base: string;
  // LocalPath is where the Factory finds its clone, empty for beside
  // the Home Repository.
  local_path: string;
  // CodeHost is the Code Host its Clone URL names, empty for none
  // Code Central supports.
  code_host: CodeHost;
  // ChangedBy are the unfinished Tickets whose Changed Repositories
  // include it, which keep it from being removed. Only get_project and
  // list_projects fill them in.
  changed_by: string[];
  // Clone is its clone as the Factory last reported it, absent while no
  // Factory is reporting.
  clone?: CloneView;
  // Landing is its effective Landing: its Own Landing, else the
  // Project's Default Landing; never default.
  landing: RepositoryLanding;
  // OwnLanding is whether Landing is its Own Landing.
  own_landing: boolean;
  // PushRemote is the git remote it is pushed to and fetched from: its
  // own, else the Project's.
  push_remote: string;
  // OwnPushRemote is whether PushRemote is its own.
  own_push_remote: boolean;
  // LocalOnlyUnderPullRequest marks a local-only Repository whose
  // Landing is Pull Request, as only a Home that lost its remote can
  // be: nothing lands there until it has another Landing or a remote.
  local_only_under_pull_request: boolean;
  // CI is its CI choice, the Home's included: its CI entry, stored or
  // filled in from its Clone URL.
  ci: CIRepositoryView;
}

// LinkView is a Spec's or Ticket's Link as reads show it: the external
// item its Integration mirrors. While it isn't detached, the title and
// description belong to the external system. Outbound marks a Link that
// doesn't own the item's definition: Code Central owns it and only
// writes to the external item.
export interface LinkView {
  integration: string;
  id: string;
  url?: string;
  external_state: ExternalState;
  detached: boolean;
  outbound: boolean;
}

// SpecRef names a Ticket's Spec.
export interface SpecRef {
  id: string;
  title: string;
}

// BlockerView is one Blocker as get_ticket shows it, after following
// Replacements. Via names the Cancelled Blocker it stands in for, if any.
// A brief view shows a Done Blocker as its ID and State only
// (TicketView.Brief), leaving out its title, via and cleared.
export interface BlockerView {
  id: string;
  title?: string;
  state: State;
  via?: string;
  // Cleared is whether it no longer blocks though it isn't Done, as one
  // on the same Spec does once it is merged into the Spec Branch. It is
  // always set, except on a brief view's Done Blocker.
  cleared?: boolean;
}

// ChangedRepositoryView is one of a Ticket's Changed Repositories as
// reads show it, in landing order.
export interface ChangedRepositoryView {
  name: string;
  branch?: string;
  commit?: string;
  // Landed is the commit that put the work into the Repository's base;
  // left out until it lands.
  landed?: LandedView;
  // NotLanded is why an Accepted Ticket hasn't landed in the Repository
  // yet: its broken base, or what the Factory last said; left out once
  // it lands, or while there's none to give.
  not_landed?: string;
  // PushedCommit is the latest commit the Factory pushed for the Ticket
  // in the Repository; left out while it has pushed none.
  pushed_commit?: PushedCommitView;
  // PullRequest is the Ticket's pull request in the Repository; left
  // out until the Pull Request Watcher reports one.
  pull_request?: PullRequestView;
  // CIResult is the Repository's CI result, from the pushed commit
  // CICommit; both are left out while it has none. CINotWatched says CI
  // Tracking never watches the Repository: it has no CI result.
  ci_result?: CIResult;
  ci_commit?: string;
  ci_not_watched?: boolean;
  // LandAnyway says the human accepted the failed CI result of the
  // latest pushed commit there, so the Factory lands it there.
  land_anyway?: boolean;
  // CIAutoFix is what Auto-fix does about the Ticket's CI failure
  // there; left out while it does nothing.
  ci_auto_fix?: CIAutoFixView;
}

// PushedCommitView is a commit the Factory pushed for a Ticket, and when
// Code Central heard of it.
export interface PushedCommitView {
  commit: string;
  pushed: string;
}

// PullRequestView is a pull request as reads show it: on a Ticket, on the
// Spec page and in the Pull Request Watcher's list.
export interface PullRequestView {
  // Repository is the Repository Name the pull request is in; left out
  // while the Project has one Repository.
  repository?: string;
  number: number;
  link: string;
  state: PullRequestState;
  // MergeCommit is the commit the Code Host merged it at, once merged.
  merge_commit?: string;
}

// CIRunView is one CI Run as reads return it, and as report_ci_runs
// takes it: the CI Watcher names what it is tracked against, a Ticket or
// a CI Rule's Spec; Code Central marks it ignored.
export interface CIRunView {
  // Repository is the Repository Name of the Repository the run is for,
  // empty for the Home Repository. With the CI Provider's run ID and
  // attempt, it keys the run.
  repository?: string;
  id: number;
  attempt: number;
  // Workflow is the workflow file's base name, such as ci.yml; Name is
  // the name it shows.
  workflow: string;
  name: string;
  branch: string;
  commit: string;
  status: CIRunStatus;
  conclusion?: CIConclusion;
  started?: string;
  finished?: string;
  url: string;
  jobs: CIJobView[];
  // Ticket or Rule is what the run is tracked against: a Ticket's ID,
  // or the ID of a CI Rule's Spec.
  ticket?: string;
  rule?: string;
  // Ignored marks a run of an Ignored workflow, which never counts
  // towards a CI result; Code Central sets it.
  ignored: boolean;
}

// CIAutoFixView is what Auto-fix does about a Ticket's CI failure in one
// Repository, worked out in Go for the UI to format (ADR 0063): the auto
// fix Ticket fixing it, the one covering it, or the chain Auto-fix
// stopped at the limit. One of them is set.
export interface CIAutoFixView {
  fixing?: AutoFixFixingView;
  covering?: AutoFixCoveringView;
  stopped?: AutoFixStoppedView;
}

// SpecMergeView is the Spec Branch commit a Ticket's work was merged
// into and when Code Central heard of it; Counts is false for a merge no
// later than the Ticket's last move back to Ready.
export interface SpecMergeView {
  // Repository is the Repository Name of the Spec Branch, left out for
  // the Home Repository.
  repository?: string;
  commit: string;
  merged: string;
  counts: boolean;
}

// CIItemView is a CI item as a Needs Me row and each listed Ticket's
// view carry it: its reason, the pushed commit, the Tickets waiting on
// it, accepted earliest first, and the failure options the human may
// choose, each an operation's name, which act on every one of them;
// none while CI unavailable.
export interface CIItemView {
  reason: NeedsMeReason;
  // Repository is the Repository Name the commit was pushed in, left
  // out while the Project has the Home Repository alone. Each option
  // acts on that Repository only.
  repository?: string;
  commit: string;
  tickets: CIItemTicket[];
  options: CIFailureOption[];
  // NewFixNote is the note New fix Ticket starts from, the Run summary
  // and the Project's Fix instructions; SendBackNote is the note Send
  // back to fix starts from, the Run summary alone. Each is left out
  // while its option isn't offered, and the human edits either before
  // choosing it.
  new_fix_note?: string;
  send_back_note?: string;
  // AutoFixStopped is the "Auto-fix stopped after N attempts" line
  // while Auto-fix has stopped at the limit on the item, which waits on
  // the human again; left out otherwise.
  auto_fix_stopped?: AutoFixStoppedView;
}

// ClaimView is one Claim as reads show it: never with its Claim ID.
export interface ClaimView {
  number: number;
  session_id?: string;
  // WorkingDir and ResumeCommand are as the holder last set them, empty
  // when unset: never a filled-in default.
  working_dir?: string;
  resume_command?: string;
  // Model and Effort are what the Claim's latest turn ran with, empty
  // meaning Claude Code's default.
  model?: string;
  effort?: string;
  started: string;
  // LastActivity is the latest write the Claim's agent made on the Ticket.
  last_activity: string;
  ended?: string;
  ended_by?: string;
  // LatestEvent is the Claim's latest Session Event, shown short; left
  // out when it has none. Computed, never stored.
  latest_event?: LatestEvent;
}

// RoundView is one Round as reads show it.
export interface RoundView {
  number: number;
  claim: number;
  session_id?: string;
  posted: string;
  questions: QuestionView[];
}

// FailureReportView is one Failure Report as reads show it.
export interface FailureReportView {
  number: number;
  claim: number;
  // SessionID, WorkingDir and ResumeCommand are copies of the Claim's,
  // made when the report was written.
  session_id?: string;
  working_dir?: string;
  resume_command?: string;
  actor: string;
  time: string;
  what_broke: string;
  why: string;
  what_to_fix: string;
  where_work_stands: string;
}

// CommentView is one comment on a Ticket.
export interface CommentView {
  number: number;
  actor: string;
  time: string;
  // the Claim a required note was made under
  claim?: number;
  body: string;
}

// MoveView is one State move. An imported Ticket's one move has no From.
export interface MoveView {
  from?: State;
  to: State;
  actor: string;
  time: string;
  claim?: number;
  via?: string;
  // Commit is the commit that put the work into the base, on a land.
  commit?: string;
  // Cause is why an auto-accept made the Move (project, ticket-label or
  // spec-label); left out on every other Move.
  cause?: AutoAcceptCause;
}

// EditView is one entry in a Spec's or Ticket's edit history. Previous
// holds the old value of each field the edit changed.
export interface EditView {
  number: number;
  actor: string;
  time: string;
  previous: Record<string, string>;
}

// AutoFixMarkView is an auto fix Ticket's Auto-fix mark as its view
// carries it.
export interface AutoFixMarkView {
  // Attempt is its Auto-fix attempt, 1 for the first in its chain.
  attempt: number;
  // Repository is the Repository Name of the commit it was opened for,
  // left out while the Project has the Home Repository alone.
  repository?: string;
  commit: string;
  // Covers are the Tickets its CI failed item listed when it was
  // opened.
  covers: string[];
  // Previous is the previous attempt's fix Ticket, left out for attempt
  // 1.
  previous?: string;
}

// ModelChoice is the model and effort a Ticket's next turn runs with, as
// far as Code Central sets them, each worked out on its own.
export interface ModelChoice {
  model: ChoiceValue;
  effort: ChoiceValue;
}

// RetroView is a Retro as a read of its target lists it.
export interface RetroView {
  id: string;
  title: string;
  state: State;
}

// LatestEvent is a Claim's latest Session Event, shown short: its text is
// one line, cut to LatestEventLimit. Computed on read, never stored.
export interface LatestEvent {
  kind: SessionEventKind;
  text: string;
  time: string;
}

// Heading is one heading of a body's outline.
export interface Heading {
  text: string;
  level: number;
  // Size is the bytes of the Section the heading opens, subsections
  // included, so a reader can weigh a Section before fetching it.
  size: number;
}

// RequirementView is the requirement block on a Spec read, present only
// when the Spec is a Requirement: it has at least one Stage Ticket.
// Nothing in it is stored.
export interface RequirementView {
  // Map is the Map the Requirement was made from, from its map Tag, set
  // only when it has no grilling Stage.
  map?: string;
  // Stages are the Stage Tickets in Stage order.
  stages: StageView[];
  // Build is how far the implementation Tickets have got.
  build: BuildProgress;
  // WaitingForFactory is whether the next Ticket can be claimed but
  // nothing has claimed it.
  waiting_for_factory: boolean;
  // Segments are the Stage strip's: one per Stage, then Build, with a
  // first grilling segment for a Requirement made from a Map (done) or
  // one submitted Straight to Spec (skipped).
  segments: Segment[];
  // Current is the Stage of the first segment neither done nor skipped,
  // else build.
  current: SegmentStage;
  // Needs are every Ticket of the Requirement waiting on the human: the
  // Stage Tickets in Stage order, then the Build Tickets in claim order.
  needs: RequirementNeed[];
  // DefaultTicket is the Ticket the Requirement opens on: the first of
  // Needs, else the current segment's, else the first unfinished Build
  // Ticket, else the last Build Ticket, else the last segment's with one.
  default_ticket?: string;
}

// LandPerSpecView is a Spec's Land per Spec status on a Spec read,
// present only while the Project is under Merge with Land per Spec on.
export interface LandPerSpecView {
  // Waiting are the Accepted Tickets waiting for the Spec to land.
  waiting: string[];
  // Ready is whether the Spec is ready to land: the Factory merges it
  // into the base.
  ready: boolean;
}

// MapView is the Map block on a Spec read, present only when the Spec is
// labelled wayfinder:map. Nothing in it is stored.
export interface MapView {
  // Decided is the Map's Wayfinder Tickets that are Done.
  decided: number;
  // Total is its Wayfinder Tickets that aren't Cancelled.
  total: number;
  // NeedsYou is its Tickets with a Needs Me reason, Prototypes included.
  needs_you: number;
  // Guided is whether its guided Tag is on: the Factory then starts its
  // next decision whenever it is idle.
  guided: boolean;
  // CanWriteSpec is whether it has no unfinished Tickets.
  can_write_spec: boolean;
  // Requirements are the Specs whose map Tag names this Map: the
  // Requirements Write the Spec made from it, in creation order.
  requirements: string[];
}

// TicketQuestions is one Ticket's Rounds in a Spec's roll-up.
export interface TicketQuestions {
  id: string;
  title: string;
  state: State;
  rounds: RoundView[];
}

// NeedsMeGroup is the Tickets waiting for one reason.
export interface NeedsMeGroup {
  reason: NeedsMeReason;
  tickets: NeedsMeRow[];
}

// HeldSessionEvent is a Session Event in a Transcript, with its sequence
// number, which rises within the Transcript and is the SSE id its stream
// resumes from.
export interface HeldSessionEvent extends SessionEvent {
  seq: number;
}

// CIProjectStatus is one Project's CI Tracking and its CI Watcher's
// status, as the CI view heads its runs with them.
export interface CIProjectStatus {
  project: string;
  tracking: boolean;
  provider: CIProvider;
  repository: string;
  project_url: string;
  watcher: WatcherView;
}

// CIRunRow is one CI Run in the CI view, with its Project.
export interface CIRunRow extends CIRunView {
  project: string;
}

// UsageOperation is one MCP operation's row: its calls, their total and
// average request and response sizes in bytes, and how many were
// rejected. Averages are rounded to the nearest byte.
export interface UsageOperation {
  op: string;
  calls: number;
  request_bytes: number;
  average_request_bytes: number;
  response_bytes: number;
  average_response_bytes: number;
  errors: number;
}

// UsageKind is one kind of session's Context Size figures: how many
// sessions there were, and the average and largest of their peaks. The
// average is rounded to the nearest token.
export interface UsageKind {
  kind: string;
  sessions: number;
  average_peak: number;
  largest_peak: number;
}

// UsageSession is one recent session: a Claim's main session, or a
// Subagent of it (Agent), with the Project, Ticket, Claim and kind of its
// latest response. Started is its first response's time, Peak the largest
// Context Size among its responses, Tokens all their tokens, and Models
// each distinct model its responses name, in order of first use. A
// Subagent has the latest non-empty Agent Type and description among its
// responses.
//
// A main session has its Subagents, oldest first, and TotalTokens, its
// Tokens and theirs; a Subagent has no Subagents and no TotalTokens. A
// main session whose only responses are its Subagents' has none of its
// own: no kind, models, peak or tokens, its Subagents' first start and
// the Project, Ticket and Claim of their latest response.
export interface UsageSession {
  project: string;
  ticket: string;
  claim: number;
  session_id: string;
  agent?: string;
  agent_type?: string;
  description?: string;
  kind: string;
  started: string;
  peak: number;
  responses: number;
  models: string[];
  tokens: number;
  total_tokens?: number;
  subagents: UsageSession[];
}

// UsageDay is one local day's token usage, by kind of session: the kinds
// with any usage that day, in kindOrder; none on a day with no usage.
// Day is YYYY-MM-DD in the service's time zone.
export interface UsageDay {
  day: string;
  kinds: UsageDayTokens[];
}

// SessionUsageResponse is one of a session's model responses: when it
// came, its Context Size and its four token counts.
export interface SessionUsageResponse extends Tokens {
  time: string;
  context_size: number;
}

// ChatFactory names the Factory holding a Conversation, by its
// Heartbeat's name and host.
export interface ChatFactory {
  name: string;
  host: string;
}

// ChatMessageView is one Chat Message. A human's holds its Text; a
// Claude's holds its Items, in the shape of Session Events (with
// permission_denials as an item of their own), and its Outcome once the
// reply has ended, with Error on a failed one.
export interface ChatMessageView {
  from: ChatAuthor;
  time: string;
  text?: string;
  items?: HeldSessionEvent[];
  outcome?: ChatOutcome;
  error?: string;
}

// LandingMethodsCapabilities is the Landing capabilities of every Landing
// Method, each as if it were the Default Landing.
export interface LandingMethodsCapabilities {
  // Merge is what the form offers with Merge drafted.
  merge: LandingMethodCapabilities;
  // Branch is what the form offers with Leave as a branch drafted.
  branch: LandingMethodCapabilities;
  // PullRequest is what the form offers with Pull Request drafted.
  pull_request: LandingMethodCapabilities;
}

// WatcherView is a Project's Watcher's status, in its kind's settings.
export interface WatcherView {
  state: WatcherState;
  // Problem, Message and Fix say what is wrong, while in error.
  problem?: WatcherProblem;
  message?: string;
  fix?: string;
  // Repositories are the Repositories it can't watch, each with its
  // problem and fix, while in error about some of them only: it carries
  // on watching the rest.
  repositories?: RepositoryProblem[];
  // RateLimitedUntil is when GitHub lets a rate-limited Watcher call it
  // again; until then it is still Watching, not in error.
  rate_limited_until?: string;
  // Since is when the Watcher went into this state; nil until it
  // reports.
  since?: string;
  // Host is the machine whose service holds the Project's Watcher
  // Lease, and so runs the Watcher, once a Lease is known.
  host?: string;
}

// OpenPullRequest is a pull request left open for an Accepted Ticket.
export interface OpenPullRequest {
  ticket: string;
  link: string;
}

// CIRuleView is one CI Rule: when Workflow fails on Branch, open a Ticket
// to fix it, in State, on the rule's own Spec, whose ID names the rule.
export interface CIRuleView {
  spec: string;
  // Workflow is a workflow file's base name or a pipeline's name, or any.
  workflow: string;
  branch: string;
  state: State;
  created: string;
}

// CIRepositoryView is the CI entry of one Repository: its CI Provider and
// what that watches, or Not watched.
export interface CIRepositoryView {
  name: string;
  not_watched: boolean;
  provider?: CIProvider;
  repository?: string;
  project_url?: string;
}

// AutoFixView is a Project's Auto-fix setting as every Project read
// returns it: the defaults while the human never set them.
export interface AutoFixView {
  on: boolean;
  // FixInstructions are appended to every fix Ticket's description.
  fix_instructions: string;
  // DefaultFixInstructions is the text FixInstructions starts from, for
  // the UI's way back to it.
  default_fix_instructions: string;
  // Limit is the Auto-fix limit: the most Auto-fix attempts per failure
  // chain, 1 to 10.
  limit: number;
}

// ModelRowView is one Models row's model and effort, each empty when the
// row leaves it to the tier below.
export interface ModelRowView {
  model: string;
  effort: string;
}

// KindModelsView is the Models row for one kind of work, a guide name.
export interface KindModelsView extends ModelRowView {
  kind: string;
}

// FactoryView is one Factory as the Project view lists it, from its last
// Heartbeat.
export interface FactoryView {
  name: string;
  host: string;
  status: FactoryStatusName;
  // Note is empty when none; a stopped Factory keeps its last one.
  note: string;
  last_heartbeat: string;
  interval_seconds: number;
  // Chat is Chat support: the Factory can run Conversations. Chat is
  // available for the Project while an Online Factory has it.
  chat: boolean;
}

// BaseView is a Project's reported base, as its Factory Status carries it;
// absent while no Factory is reporting.
export interface BaseView {
  state: BaseState;
  // Local and Remote are the local and remote base commits.
  local: string;
  remote: string;
  // Branch is the base branch's name, when the Factory reported it.
  branch?: string;
  at: string;
}

// PlanLimits are a Factory's Plan Limits, as it reports them and as the
// Project's Factory Status shows them.
export interface PlanLimits {
  // ObservedAt is when the Factory read the figures; one later than
  // Code Central's receipt is kept as the receipt time.
  observed_at: string;
  // FiveHour and Weekly are each left out when the Factory has no
  // figures for that window.
  five_hour?: PlanLimitWindow;
  weekly?: PlanLimitWindow;
}

// CloneView is a Repository's clone as the Factory last reported it;
// absent while no Factory is reporting.
export interface CloneView {
  state: CloneState;
  path: string;
  problem?: string;
  // Since is when the Factory first reported it in this state with
  // this problem.
  since: string;
}

// LandedView is the commit that put a Ticket's work into a Repository's
// base, and when Code Central heard of it.
export interface LandedView {
  commit: string;
  time: string;
}

// CIJobView is one job of a CI Run; its conclusion is empty until it
// ends.
export interface CIJobView {
  name: string;
  conclusion?: CIConclusion;
  url: string;
}

// AutoFixFixingView is the auto fix Ticket fixing the failure of a
// Ticket's latest pushed commit: attempt Attempt of the Auto-fix limit,
// Limit.
export interface AutoFixFixingView {
  fix_ticket: string;
  attempt: number;
  limit: number;
}

// AutoFixCoveringView is the open auto fix Ticket covering a Ticket whose
// later commit carries the failure it fixes, and the commit it was opened
// for.
export interface AutoFixCoveringView {
  fix_ticket: string;
  commit: string;
}

// AutoFixStoppedView is the chain Auto-fix stopped at the limit on a CI
// failed item, which comes back to the human: "Auto-fix stopped after N
// attempts", Attempts being the N auto fix Tickets, attempt 1 first.
export interface AutoFixStoppedView {
  attempts: string[];
}

// CIItemTicket is one Ticket a CI item lists, with its Spec.
export interface CIItemTicket {
  id: string;
  title: string;
  spec: string;
}

// QuestionView is one Question: open, answered or dismissed.
export interface QuestionView {
  number: number;
  title: string;
  body: string;
  recommended?: string;
  status: QuestionStatus;
  answer?: string;
  closed?: string;
}

// ChoiceValue is one of a Model Choice's values with its source; Value is
// empty when the source is none. Kind names the kind of work whose
// Models row set it, only when the source is project_kind.
export interface ChoiceValue {
  value?: string;
  source: ChoiceSource;
  kind?: string;
}

// StageView is one Stage Ticket: its Stage name, Ticket ID, State and
// Needs Me reason, if any.
export interface StageView {
  name: StageName;
  ticket: string;
  state: State;
  needs_me_reason?: NeedsMeReason;
}

// BuildProgress is the implementation Tickets Done over their total,
// leaving out Cancelled ones.
export interface BuildProgress {
  done: number;
  total: number;
}

// Segment is one segment of a Requirement's Stage strip.
export interface Segment {
  stage: SegmentStage;
  progress: SegmentProgress;
  // Ticket is the Stage Ticket; Build and a Map's segment have none.
  ticket?: string;
  // Map is the Map the Requirement was made from, on the segment that
  // stands in for its grilling Stage.
  map?: string;
  // Reason is why the segment needs the human: its Stage Ticket's
  // reason, or Build's first need's.
  reason?: NeedsMeReason;
}

// RequirementNeed is one Ticket of a Requirement waiting on the human,
// with its Stage when it is a Stage Ticket.
export interface RequirementNeed {
  ticket: string;
  reason: NeedsMeReason;
  stage?: StageName;
}

// NeedsMeRow is one waiting Ticket with what its one-line detail needs.
// Since is when it started waiting: the Round posted, the last answer,
// the last activity (Silent Claim, so the quiet time is now minus it),
// the last move (Long Claim),
// the Failure Report, the finish, the first failed CI Run finishing (CI
// failed), the accept (To merge, and Accepted but not landed), the push
// (CI unavailable),
// the Blocker's cancel, or the Ticket's creation (New issue). Only the
// detail field for its reason is set. A CI failed, CI cancelled or CI
// unavailable row is one per pushed commit, with no Ticket: its ID is
// empty, and CIItem lists the Tickets waiting on the commit.
export interface NeedsMeRow {
  project: string;
  id: string;
  title: string;
  state: State;
  reason: NeedsMeReason;
  since: string;
  // FocusItem says the Project's Focus Kinds leave the row's reason on.
  // Focus Kinds mark rows and filter nothing.
  focus_item: boolean;
  // Round is the latest Round (Needs Answer).
  round?: RoundSummary;
  // Failure is the latest Failure Report (Failed).
  failure?: FailureSummary;
  // Summary is the first line of the finish summary (In Review).
  summary?: string;
  // Branch is the Ticket's branch, for the human to merge (To merge).
  branch?: string;
  // CIFailure is what failed on the pushed commit (CI failed).
  ci_failure?: CIFailureSummary;
  // CIUnavailable says which: the CI Watcher not Watching, or no CI
  // Runs for the pushed commit (CI unavailable).
  ci_unavailable?: CIUnavailableView;
  // CIItem is the pushed commit's item: the Tickets waiting on it and
  // the failure options (CI failed, CI cancelled and CI unavailable).
  ci_item?: CIItemView;
  // Blocker is the Cancelled Blocker (blocked by a Cancelled Ticket).
  blocker?: BlockerView;
  // Link is the Ticket's Link, whatever the reason: the row's badge, and
  // the external item when closed externally.
  link?: LinkView;
  // Requirement is set when the Ticket's Spec is a Requirement.
  requirement?: NeedsMeRequirement;
  // Spec is the Spec a Map Ticket or Prototype is on, as its context,
  // set when its Spec isn't a Requirement (Spec 213).
  spec?: NeedsMeSpec;
  // Prototype is set on a Ticket labelled prototype, for its badge.
  prototype?: boolean;
  // Retro is set on a Ticket labelled retro, for its badge.
  retro?: boolean;
  // CIResult is the Ticket's CI result, whatever the reason, or a CI
  // item's commit's, for the row's badge; left out for a Ticket never
  // pushed while CI Tracking was on.
  ci_result?: CIResult;
  // PullRequest is the Ticket's pull request, for its item's link; left
  // out until the Pull Request Watcher reports one.
  pull_request?: PullRequestView;
  // ClosedPullRequests are the Ticket's pull requests closed without
  // merging, each naming its Repository while the Project has several,
  // in landing order (Pull request closed).
  closed_pull_requests?: PullRequestView[];
  // BaseDiverged is the local and remote base commits (Base diverged,
  // whose row has no Ticket: its ID is empty).
  base_diverged?: BaseDivergedView;
  // BaseMissing is the missing base's branch and the fix (Base missing,
  // whose row has no Ticket either).
  base_missing?: BaseMissingView;
  // RepositoryMissing is the missing Repository's path, Clone URL,
  // problem and fix (Repository missing, whose row has no Ticket).
  repository_missing?: RepositoryMissingView;
  // NotLanded is the Repositories the Ticket has landed in and those it
  // hasn't, with why (Accepted but not landed, while the Project has
  // several Repositories).
  not_landed?: NotLandedView;
}

// SessionEvent is one thing a Claim's session did, as posted: agent text,
// a tool call, a tool result or a Factory log line. Tool and Text are
// opaque strings.
export interface SessionEvent {
  time: string;
  kind: SessionEventKind;
  text: string;
  tool?: string;
  tool_use_id?: string;
  is_error?: boolean;
  truncated?: boolean;
}

// UsageDayTokens is one kind's tokens on one day, by token type.
export interface UsageDayTokens extends Tokens {
  kind: string;
}

// Tokens are a model response's four token counts.
export interface Tokens {
  input_tokens: number;
  cache_write_tokens: number;
  cache_read_tokens: number;
  output_tokens: number;
}

// LandingMethodCapabilities is what the Options form offers with one
// Landing Method drafted as the Default Landing: its Landing
// capabilities.
export interface LandingMethodCapabilities {
  // OffersPush is whether the Push checkbox is offered.
  offers_push: boolean;
  // OffersLandPerSpec is whether Land per Spec can be changed.
  offers_land_per_spec: boolean;
  // ShowsCodeHost is whether the Code Host worked out from the Push
  // remote URL is shown.
  shows_code_host: boolean;
  // UsesAzureReposPAT is whether the PAT variable is used.
  uses_azure_repos_pat: boolean;
}

// RepositoryProblem is one Repository a Watcher can't watch, by
// Repository Name, with what is wrong and its fix (Spec
// code-central-848): the Watcher carries on with the others.
export interface RepositoryProblem {
  repository: string;
  problem?: WatcherProblem;
  message: string;
  fix?: string;
}

// PlanLimitWindow is one window of the Plan Limits.
export interface PlanLimitWindow {
  // UsedPercent is the share of the window's limit used, 0 to 100.
  used_percent: number;
  resets_at: string;
}

// RoundSummary is a Round's number and how many of its Questions are open.
export interface RoundSummary {
  number: number;
  open: number;
  questions: number;
}

// FailureSummary is the latest Failure Report's headline (the first line
// of what_broke) and how many reports the Ticket has.
export interface FailureSummary {
  headline: string;
  reports: number;
}

// CIFailureSummary is what failed on a CI failed item's pushed commit:
// the commit and its failed runs' workflow file names.
export interface CIFailureSummary {
  commit: string;
  workflows: string[];
}

// CIUnavailableView is a CI unavailable row's detail: the cause, the
// pushed commit and when it was pushed, and, while the CI Watcher is in
// error, its message.
export interface CIUnavailableView {
  cause: CIUnavailableCause;
  commit: string;
  pushed: string;
  message?: string;
}

// NeedsMeRequirement is the Requirement a Needs Me row's Ticket is on:
// its Spec ID and title, and the Ticket's Stage, set only on a Stage
// Ticket.
export interface NeedsMeRequirement {
  spec: string;
  title: string;
  stage?: StageName;
}

// NeedsMeSpec is the Spec a Needs Me row's Map Ticket or Prototype is on:
// its Spec ID and title, and whether it is a Map.
export interface NeedsMeSpec {
  spec: string;
  title: string;
  map?: boolean;
}

// BaseDivergedView is a Base diverged item's detail: both commits and the
// base branch, and the Repository whose base it is while the Project has
// several.
export interface BaseDivergedView {
  repository?: string;
  base?: string;
  local: string;
  remote: string;
}

// BaseMissingView is a Base missing item's detail: the branch and the fix,
// and the Repository whose base it is while the Project has several.
export interface BaseMissingView {
  repository?: string;
  base: string;
  fix: string;
}

// RepositoryMissingView is a Repository missing item's detail: the
// Repository, its path and Clone URL, what is wrong and the fix.
export interface RepositoryMissingView {
  repository: string;
  path: string;
  clone_url: string;
  problem: string;
  fix: string;
}

// NotLandedView is an Accepted but not landed item's Repositories, while
// the Project has several: those its Ticket has landed in, and those it
// hasn't, each with why, in landing order.
export interface NotLandedView {
  landed: string[];
  not_landed: NotLandedRepositoryView[];
}

// NotLandedRepositoryView is a Changed Repository a Ticket hasn't landed
// in, and why.
export interface NotLandedRepositoryView {
  name: string;
  // Reason is why: its broken base, or what the Factory last said about
  // it since the Ticket was accepted; left out when there's none to
  // give.
  reason?: string;
}
